{
  "command": "ls client-artifacts/ | head; echo "=== look at a reasoning response ==="; python3 - <<'EOF'
import json, glob, os
# find response json for the reasoning items (evidence id 00a7b9a6...)
for f in glob.glob("client-artifacts/*.response.json"):
    d = json.load(open(f))
    sr = d.get("stop_reason")
    content = d.get("content", [])
    if sr == "max_tokens":
        print(os.path.basename(f), "stop=", sr, "content_types=", [c.get("type") for c in content])
        for c in content:
            if c.get("type") == "text":
                print("  TEXT:", c["text"][:500])
            elif c.get("type") == "thinking":
                print("  THINKING:", str(c.get("thinking"))[:300])
EOF",
  "description": "Inspect empty reasoning responses"
}
